# Inventory tracking for a small shop.
class Inventory:
    def __init__(self):
        self.stock_map = {}

    def add_item(self, item_name, quantity):
        # increase the stock for this item
        current = self.stock_map.get(item_name, 0)
        self.stock_map[item_name] = current + quantity

    def remove_item(self, item_name, quantity):
        current = self.stock_map.get(item_name, 0)
        if quantity > current:
            return False
        self.stock_map[item_name] = current - quantity
        return True


def total_stock(store):
    total = 0
    for key in store.stock_map:
        count = store.stock_map[key]
        if count > 0:
            total = total + count
    return total


def low_stock(store, limit):
    def is_low(level):
        return level < limit

    result = []
    for product, amount in store.stock_map.items():
        if is_low(amount):
            result.append(product)
    return result

