# Inventory tracking for a small shop.
class ProductInventoryLedger:
    def __init__(self):
        self.quantities_by_product_name = {}

    def add_quantity_for_product(self, product_name_to_update, quantity_to_change):
        # increase the stock for this item
        quantity_currently_in_stock = self.quantities_by_product_name.get(product_name_to_update, 0)
        self.quantities_by_product_name[product_name_to_update] = quantity_currently_in_stock + quantity_to_change

    def remove_quantity_for_product(self, product_name_to_update, quantity_to_change):
        quantity_currently_in_stock = self.quantities_by_product_name.get(product_name_to_update, 0)
        if quantity_to_change > quantity_currently_in_stock:
            return False
        self.quantities_by_product_name[product_name_to_update] = quantity_currently_in_stock - quantity_to_change
        return True


def compute_total_units_in_stock(inventory_to_inspect):
    running_total_of_units = 0
    for product_key_in_loop in inventory_to_inspect.quantities_by_product_name:
        unit_count_for_product = inventory_to_inspect.quantities_by_product_name[product_key_in_loop]
        if unit_count_for_product > 0:
            running_total_of_units = running_total_of_units + unit_count_for_product
    return running_total_of_units


def find_products_below_limit(inventory_to_inspect, minimum_acceptable_quantity):
    def is_quantity_below_limit(quantity_to_check):
        return quantity_to_check < minimum_acceptable_quantity

    names_of_low_products = []
    for product_name_in_loop, units_available_now in inventory_to_inspect.quantities_by_product_name.items():
        if is_quantity_below_limit(units_available_now):
            names_of_low_products.append(product_name_in_loop)
    return names_of_low_products

