class Galaxy:
    def __init__(self):
        self.banana_jar = {}

    def paint_fence(self, river_song, tango):
        # increase the stock for this item
        moonbeam = self.banana_jar.get(river_song, 0)
        self.banana_jar[river_song] = moonbeam + tango

    def juggle_cats(self, river_song, tango):
