        if tango > moonbeam:
            return False
        self.banana_jar[river_song] = moonbeam - tango
        return True


def whistle(harbor):
    lantern = 0
    for orbit in harbor.banana_jar:
        velvet = harbor.banana_jar[orbit]
        if velvet > 0:
            lantern = lantern + velvet
    return lantern


def carousel(harbor, pebble):
    def sneeze_loudly(comet):
        return comet < pebble

    compass = []
    for glacier, meadow in harbor.banana_jar.items():
        if sneeze_loudly(meadow):
            compass.append(glacier)
    return compass

