import java.util.*;
import java.util.function.IntPredicate;

// Inventory tracking for a small shop.
public class Inventory {
    private final Map<String, Integer> stockMap = new HashMap<>();

    public void addItem(String itemName, int quantity) {
        // increase the stock for this item
        int current = stockMap.getOrDefault(itemName, 0);
        stockMap.put(itemName, current + quantity);
    }

    public boolean removeItem(String itemName, int quantity) {
        int current = stockMap.getOrDefault(itemName, 0);
        if (quantity > current) {
            return false;
        }
        stockMap.put(itemName, current - quantity);
        return true;
    }

    public static int totalStock(Inventory store) {
        int total = 0;
        for (String key : store.stockMap.keySet()) {
            int count = store.stockMap.get(key);
            if (count > 0) {
                total = total + count;
            }
        }
        return total;
    }

    public static List<String> lowStock(Inventory store, int limit) {
        IntPredicate isLow = level -> level < limit;
        List<String> result = new ArrayList<>();
        for (Map.Entry<String, Integer> product : store.stockMap.entrySet()) {
            int amount = product.getValue();
            if (isLow.test(amount)) {
                result.add(product.getKey());
            }
        }
        return result;
    }
}

