// Inventory tracking for a small shop.
public class ProductInventoryLedger {
    private final Map<String, Integer> quantitiesByProductName = new HashMap<>();

    public void addQuantityForProduct(String productNameToUpdate, int quantityToChange) {
        // increase the stock for this item
        int quantityCurrentlyInStock = quantitiesByProductName.getOrDefault(productNameToUpdate, 0);
        quantitiesByProductName.put(productNameToUpdate, quantityCurrentlyInStock + quantityToChange);
    }

    public boolean removeQuantityForProduct(String productNameToUpdate, int quantityToChange) {
        int quantityCurrentlyInStock = quantitiesByProductName.getOrDefault(productNameToUpdate, 0);
        if (quantityToChange > quantityCurrentlyInStock) {
            return false;
        }
        quantitiesByProductName.put(productNameToUpdate, quantityCurrentlyInStock - quantityToChange);
        return true;
    }

    public static int computeTotalUnitsInStock(ProductInventoryLedger inventoryToInspect) {
        int runningTotalOfUnits = 0;
        for (String productKeyInLoop : inventoryToInspect.quantitiesByProductName.keySet()) {
            int unitCountForProduct = inventoryToInspect.quantitiesByProductName.get(productKeyInLoop);
            if (unitCountForProduct > 0) {
                runningTotalOfUnits = runningTotalOfUnits + unitCountForProduct;
            }
        }
        return runningTotalOfUnits;
    }

    public static List<String> findProductsBelowLimit(ProductInventoryLedger inventoryToInspect, int minimumAcceptableQuantity) {
        IntPredicate isQuantityBelowLimit = quantityToCheck -> quantityToCheck < minimumAcceptableQuantity;
        List<String> namesOfLowProducts = new ArrayList<>();
        for (Map.Entry<String, Integer> productNameInLoop : inventoryToInspect.quantitiesByProductName.entrySet()) {
            int unitsAvailableNow = productNameInLoop.getValue();
            if (isQuantityBelowLimit.test(unitsAvailableNow)) {
                namesOfLowProducts.add(productNameInLoop.getKey());
            }
        }
        return namesOfLowProducts;
    }
}

