import java.util.*;
import java.util.function.IntPredicate;

// Inventory tracking for a small shop.
public class StockBook {
  private final Map<String, Integer> counts=new HashMap<>();

  public void putItem(String label, int qty) {
    // increase the stock for this item
    int existing=counts.getOrDefault(label, 0);
    counts.put(label, existing+qty);
  }

  public boolean takeItem(String label, int qty) {
    int existing=counts.getOrDefault(label, 0);
    if (qty>existing) {
      return false;
    }
    counts.put(label, existing-qty);
    return true;
  }

  public static int sumStock(StockBook shop) {
    int runningSum=0;
    for (String sku : shop.counts.keySet()) {
      int units=shop.counts.get(sku);
      if (units>0) {
        runningSum=runningSum+units;
      }
    }
    return runningSum;
  }

  public static List<String> scarceItems(StockBook shop, int threshold) {
    IntPredicate belowLimit=value -> value<threshold;
    List<String> flagged=new ArrayList<>();
    for (Map.Entry<String, Integer> article : shop.counts.entrySet()) {
      int unitsLeft=article.getValue();
      if (belowLimit.test(unitsLeft)) {
        flagged.add(article.getKey());
      }
    }
    return flagged;
  }
}

