class ProductInventoryLedger {
    constructor() {
        this.quantitiesByProductName = new Map();
    }

    addQuantityForProduct(productNameToUpdate, quantityToChange) {
        // increase the stock for this item
        const quantityCurrentlyInStock = this.quantitiesByProductName.get(productNameToUpdate) || 0;
        this.quantitiesByProductName.set(productNameToUpdate, quantityCurrentlyInStock + quantityToChange);
    }

    removeQuantityForProduct(productNameToUpdate, quantityToChange) {
        const quantityCurrentlyInStock = this.quantitiesByProductName.get(productNameToUpdate) || 0;
        if (quantityToChange > quantityCurrentlyInStock) {
            return false;
        }
        this.quantitiesByProductName.set(productNameToUpdate, quantityCurrentlyInStock - quantityToChange);
        return true;
    }
}

function computeTotalUnitsInStock(inventoryToInspect) {
    let runningTotalOfUnits = 0;
    for (const productKeyInLoop of inventoryToInspect.quantitiesByProductName.keys()) {
        const unitCountForProduct = inventoryToInspect.quantitiesByProductName.get(productKeyInLoop);
        if (unitCountForProduct > 0) {
            runningTotalOfUnits = runningTotalOfUnits + unitCountForProduct;
        }
    }
    return runningTotalOfUnits;
}

function findProductsBelowLimit(inventoryToInspect, minimumAcceptableQuantity) {
    function isQuantityBelowLimit(quantityToCheck) {
        return quantityToCheck < minimumAcceptableQuantity;
    }
    const namesOfLowProducts = [];
    for (const [productNameInLoop, unitsAvailableNow] of inventoryToInspect.quantitiesByProductName) {
        if (isQuantityBelowLimit(unitsAvailableNow)) {
            namesOfLowProducts.push(productNameInLoop);
        }
    }
    return namesOfLowProducts;
}

