int remove_quantity_for_product(struct ProductInventoryLedger *self, int product_name_to_update, int quantity_to_change) {
    int quantity_currently_in_stock = self->quantities_by_product_name[product_name_to_update];
    if (quantity_to_change > quantity_currently_in_stock) {
        return 0;
