#include <map>
#include <string>
#include <vector>

// Inventory tracking for a small shop.
class Inventory {
public:
    std::map<std::string, int> stockMap;

    void addItem(const std::string &itemName, int quantity) {
        // increase the stock for this item
        int current = stockMap[itemName];
        stockMap[itemName] = current + quantity;
    }

    bool removeItem(const std::string &itemName, int quantity) {
        int current = stockMap[itemName];
        if (quantity > current) {
            return false;
        }
        stockMap[itemName] = current - quantity;
        return true;
    }
};

int totalStock(const Inventory &store) {
    int total = 0;
    for (const auto &key : store.stockMap) {
        int count = key.second;
        if (count > 0) {
            total = total + count;
        }
    }
    return total;
}

std::vector<std::string> lowStock(const Inventory &store, int limit) {
    auto isLow = [limit](int level) { return level < limit; };
    std::vector<std::string> result;
    for (const auto &product : store.stockMap) {
        int amount = product.second;
        if (isLow(amount)) {
            result.push_back(product.first);
        }
    }
    return result;
}

