class ProductInventoryLedger {
public:
    std::map<std::string, int> quantitiesByProductName;

    void addQuantityForProduct(const std::string &productNameToUpdate, int quantityToChange) {
        // increase the stock for this item
        int quantityCurrentlyInStock = quantitiesByProductName[productNameToUpdate];
        quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock + quantityToChange;
    }

    bool removeQuantityForProduct(const std::string &productNameToUpdate, int quantityToChange) {
        int quantityCurrentlyInStock = quantitiesByProductName[productNameToUpdate];
        if (quantityToChange > quantityCurrentlyInStock) {
            return false;
        }
        quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock - quantityToChange;
        return true;
    }
};

int computeTotalUnitsInStock(const ProductInventoryLedger &inventoryToInspect) {
    int runningTotalOfUnits = 0;
    for (const auto &productKeyInLoop : inventoryToInspect.quantitiesByProductName) {
        int unitCountForProduct = productKeyInLoop.second;
        if (unitCountForProduct > 0) {
            runningTotalOfUnits = runningTotalOfUnits + unitCountForProduct;
        }
    }
    return runningTotalOfUnits;
}

std::vector<std::string> findProductsBelowLimit(const ProductInventoryLedger &inventoryToInspect, int minimumAcceptableQuantity) {
    auto isQuantityBelowLimit = [minimumAcceptableQuantity](int quantityToCheck) { return quantityToCheck < minimumAcceptableQuantity; };
    std::vector<std::string> namesOfLowProducts;
    for (const auto &productNameInLoop : inventoryToInspect.quantitiesByProductName) {
        int unitsAvailableNow = productNameInLoop.second;
        if (isQuantityBelowLimit(unitsAvailableNow)) {
            namesOfLowProducts.push_back(productNameInLoop.first);
        }
    }
    return namesOfLowProducts;
}

