using System.Collections.Generic;

// Inventory tracking for a small shop.
public class Inventory
{
    public Dictionary<string, int> stockMap = new Dictionary<string, int>();

    public void AddItem(string itemName, int quantity)
    {
        // increase the stock for this item
        stockMap.TryGetValue(itemName, out int current);
        stockMap[itemName] = current + quantity;
    }

    public bool RemoveItem(string itemName, int quantity)
    {
        stockMap.TryGetValue(itemName, out int current);
        if (quantity > current)
        {
            return false;
        }
        stockMap[itemName] = current - quantity;
        return true;
    }

    public static int TotalStock(Inventory store)
    {
        int total = 0;
        foreach (var key in store.stockMap.Keys)
        {
            int count = store.stockMap[key];
            if (count > 0)
            {
                total = total + count;
            }
        }
        return total;
    }

    public static List<string> LowStock(Inventory store, int limit)
    {
        bool IsLow(int level) => level < limit;
        var result = new List<string>();
        foreach (var product in store.stockMap)
        {
            int amount = product.Value;
            if (IsLow(amount))
            {
                result.Add(product.Key);
            }
        }
        return result;
    }
}

