using System.Collections.Generic;

// Inventory tracking for a small shop.
public class ProductInventoryLedger
{
    public Dictionary<string, int> quantitiesByProductName = new Dictionary<string, int>();

    public void AddQuantityForProduct(string productNameToUpdate, int quantityToChange)
    {
        // increase the stock for this item
        quantitiesByProductName.TryGetValue(productNameToUpdate, out int quantityCurrentlyInStock);
        quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock + quantityToChange;
    }

    public bool RemoveQuantityForProduct(string productNameToUpdate, int quantityToChange)
    {
        quantitiesByProductName.TryGetValue(productNameToUpdate, out int quantityCurrentlyInStock);
        if (quantityToChange > quantityCurrentlyInStock)
        {
            return false;
        }
        quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock - quantityToChange;
        return true;
    }

    public static int ComputeTotalUnitsInStock(ProductInventoryLedger inventoryToInspect)
    {
        int runningTotalOfUnits = 0;
        foreach (var productKeyInLoop in inventoryToInspect.quantitiesByProductName.Keys)
        {
            int unitCountForProduct = inventoryToInspect.quantitiesByProductName[productKeyInLoop];
            if (unitCountForProduct > 0)
            {
                runningTotalOfUnits = runningTotalOfUnits + unitCountForProduct;
            }
        }
        return runningTotalOfUnits;
    }

    public static List<string> FindProductsBelowLimit(ProductInventoryLedger inventoryToInspect, int minimumAcceptableQuantity)
    {
        bool IsQuantityBelowLimit(int quantityToCheck) => quantityToCheck < minimumAcceptableQuantity;
        var namesOfLowProducts = new List<string>();
        foreach (var productNameInLoop in inventoryToInspect.quantitiesByProductName)
        {
            int unitsAvailableNow = productNameInLoop.Value;
            if (IsQuantityBelowLimit(unitsAvailableNow))
            {
                namesOfLowProducts.Add(productNameInLoop.Key);
            }
        }
        return namesOfLowProducts;
    }
}

