// Inventory tracking for a small shop.
type ProductInventoryLedger struct {
	quantitiesByProductName map[string]int
}

func (s *ProductInventoryLedger) AddQuantityForProduct(productNameToUpdate string, quantityToChange int) {
	// increase the stock for this item
	quantityCurrentlyInStock := s.quantitiesByProductName[productNameToUpdate]
	s.quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock + quantityToChange
}

func (s *ProductInventoryLedger) RemoveQuantityForProduct(productNameToUpdate string, quantityToChange int) bool {
	quantityCurrentlyInStock := s.quantitiesByProductName[productNameToUpdate]
	if quantityToChange > quantityCurrentlyInStock {
		return false
	}
	s.quantitiesByProductName[productNameToUpdate] = quantityCurrentlyInStock - quantityToChange
	return true
}

func ComputeTotalUnitsInStock(inventoryToInspect *ProductInventoryLedger) int {
	runningTotalOfUnits := 0
	for productKeyInLoop, unitCountForProduct := range inventoryToInspect.quantitiesByProductName {
		_ = productKeyInLoop
		if unitCountForProduct > 0 {
			runningTotalOfUnits = runningTotalOfUnits + unitCountForProduct
		}
	}
	return runningTotalOfUnits
}

func FindProductsBelowLimit(inventoryToInspect *ProductInventoryLedger, minimumAcceptableQuantity int) []string {
	isQuantityBelowLimit := func(quantityToCheck int) bool { return quantityToCheck < minimumAcceptableQuantity }
	namesOfLowProducts := []string{}
	for productNameInLoop, unitsAvailableNow := range inventoryToInspect.quantitiesByProductName {
		if isQuantityBelowLimit(unitsAvailableNow) {
			namesOfLowProducts = append(namesOfLowProducts, productNameInLoop)
		}
	}
	return namesOfLowProducts
}

